<script lang="ts">let { data, form } = $props();</script>
<section class="card join"><p class="eyebrow">Invitation</p><h1>Join {data.roomName}</h1>{#if !data.signedIn}<p class="muted">Sign in with your existing account or create an account to request approval from this room's creator.</p><div class="button-row"><a class="button" href="/login?room={data.roomId}">Sign in to join</a><a class="secondary" href="/signup?room={data.roomId}">Create account</a></div>{:else if data.alreadyMember}<p>You already belong to this room.</p><form method="POST" action="/rooms/switch"><input type="hidden" name="roomId" value={data.roomId} /><button class="button">Open this room</button></form>{:else}<p class="muted">Enter this room's PIN. The creator will review your request.</p><form method="POST"><label for="pin">Room PIN</label><input id="pin" name="pin" type="password" inputmode="numeric" required />{#if form?.message}<p class="error" role="alert">{form.message}</p>{/if}<button class="button">Request to join</button></form>{/if}</section><style>.join{max-width:540px;margin:6vh auto}</style>
